|    = {AB: 1, AO: 1, BO: -1/2, AC: -1, CO: 1/2, DE: -1/2, DO: 1, EZ: -1/2, OZ: 1, AX: -1, UX: 1/2, AY: -1, UY: 1/2, UZ: -1}
| Premise ∠(BC,BO) = ∠(CO,BC) gives a linear equation with coefficients {BC: -2, BO: 1, CO: 1}
| Then {AB: 1, AO: 1, BO: -1/2, AC: -1, CO: 1/2, DE: -1/2, DO: 1, EZ: -1/2, OZ: 1, AX: -1, UX: 1/2, AY: -1, UY: 1/2, UZ: -1} + 1/2 x {BC: -2, BO: 1, CO: 1}
|    = {AB: 1, AO: 1, AC: -1, CO: 1, DE: -1/2, DO: 1, EZ: -1/2, OZ: 1, AX: -1, UX: 1/2, AY: -1, UY: 1/2, UZ: -1, BC: -1}
| Premise ∠(CO,CZ) = ∠(CZ,OZ) gives a linear equation with coefficients {CO: 1, CZ: -2, OZ: 1}
| Then {AB: 1, AO: 1, AC: -1, CO: 1, DE: -1/2, DO: 1, EZ: -1/2, OZ: 1, AX: -1, UX: 1/2, AY: -1, UY: 1/2, UZ: -1, BC: -1} + -1 x {CO: 1, CZ: -2, OZ: 1}
|    = {AB: 1, AO: 1, AC: -1, DE: -1/2, DO: 1, EZ: -1/2, AX: -1, UX: 1/2, AY: -1, UY: 1/2, UZ: -1, BC: -1, CZ: 2}
| Premise ∠(CX,CZ) = ∠(DX,DZ) gives a linear equation with coefficients {CX: -1, CZ: 1, DX: 1, DZ: -1}
| Then {AB: 1, AO: 1, AC: -1, DE: -1/2, DO: 1, EZ: -1/2, AX: -1, UX: 1/2, AY: -1, UY: 1/2, UZ: -1, BC: -1, CZ: 2} + -2 x {CX: -1, CZ: 1, DX: 1, DZ: -1}
|    = {AB: 1, AO: 1, AC: -1, DE: -1/2, DO: 1, EZ: -1/2, AX: -1, UX: 1/2, AY: -1, UY: 1/2, UZ: -1, BC: -1, CX: 2, DX: -2, DZ: 2}
| Premise ∠(DE,DZ) = ∠(DZ,EZ) gives a linear equation with coefficients {DE: 1, DZ: -2, EZ: 1}
| Then {AB: 1, AO: 1, AC: -1, DE: -1/2, DO: 1, EZ: -1/2, AX: -1, UX: 1/2, AY: -1, UY: 1/2, UZ: -1, BC: -1, CX: 2, DX: -2, DZ: 2} + 1/2 x {DE: 1, DZ: -2, EZ: 1}
|    = {AB: 1, AO: 1, AC: -1, DO: 1, AX: -1, UX: 1/2, AY: -1, UY: 1/2, UZ: -1, BC: -1, CX: 2, DX: -2, DZ: 1}
| Premise ∠(DO,DW) = ∠(DW,OW) gives a linear equation with coefficients {DO: 1, DW: -2, OW: 1}
| Then {AB: 1, AO: 1, AC: -1, DO: 1, AX: -1, UX: 1/2, AY: -1, UY: 1/2, UZ: -1, BC: -1, CX: 2, DX: -2, DZ: 1} + -1 x {DO: 1, DW: -2, OW: 1}
|    = {AB: 1, AO: 1, AC: -1, AX: -1, UX: 1/2, AY: -1, UY: 1/2, UZ: -1, BC: -1, CX: 2, DX: -2, DZ: 1, DW: 2, OW: -1}
| Premise ∠(UX,XY) = ∠(XY,UY) gives a linear equation with coefficients {UX: -1, UY: -1, XY: 2}
| Then {AB: 1, AO: 1, AC: -1, AX: -1, UX: 1/2, AY: -1, UY: 1/2, UZ: -1, BC: -1, CX: 2, DX: -2, DZ: 1, DW: 2, OW: -1} + 1/2 x {UX: -1, UY: -1, XY: 2}
|    = {AB: 1, AO: 1, AC: -1, AX: -1, AY: -1, UZ: -1, BC: -1, CX: 2, DX: -2, DZ: 1, DW: 2, OW: -1, XY: 1}
| Premise AC ∥ AX gives a linear equation with coefficients {AC: 1, AX: -1}
| Then {AB: 1, AO: 1, AC: -1, AX: -1, AY: -1, UZ: -1, BC: -1, CX: 2, DX: -2, DZ: 1, DW: 2, OW: -1, XY: 1} + 1 x {AC: 1, AX: -1}
|    = {AB: 1, AO: 1, AX: -2, AY: -1, UZ: -1, BC: -1, CX: 2, DX: -2, DZ: 1, DW: 2, OW: -1, XY: 1}
| Premise AO ∥ AW gives a linear equation with coefficients {AO: 1, AW: -1}
| Then {AB: 1, AO: 1, AX: -2, AY: -1, UZ: -1, BC: -1, CX: 2, DX: -2, DZ: 1, DW: 2, OW: -1, XY: 1} + -1 x {AO: 1, AW: -1}
|    = {AB: 1, AX: -2, AY: -1, UZ: -1, BC: -1, CX: 2, DX: -2, DZ: 1, DW: 2, OW: -1, XY: 1, AW: 1}
| Premise AY ∥ AB gives a linear equation with coefficients {AB: 1, AY: -1}
| Then {AB: 1, AX: -2, AY: -1, UZ: -1, BC: -1, CX: 2, DX: -2, DZ: 1, DW: 2, OW: -1, XY: 1, AW: 1} + -1 x {AB: 1, AY: -1}
|    = {AX: -2, UZ: -1, BC: -1, CX: 2, DX: -2, DZ: 1, DW: 2, OW: -1, XY: 1, AW: 1}
| Premise CX ∥ AX gives a linear equation with coefficients {AX: 1, CX: -1}
| Then {AX: -2, UZ: -1, BC: -1, CX: 2, DX: -2, DZ: 1, DW: 2, OW: -1, XY: 1, AW: 1} + 2 x {AX: 1, CX: -1}
|    = {UZ: -1, BC: -1, DX: -2, DZ: 1, DW: 2, OW: -1, XY: 1, AW: 1}
| Premise DX ∥ DW gives a linear equation with coefficients {DW: 1, DX: -1}
| Then {UZ: -1, BC: -1, DX: -2, DZ: 1, DW: 2, OW: -1, XY: 1, AW: 1} + -2 x {DW: 1, DX: -1}
|    = {UZ: -1, BC: -1, DZ: 1, OW: -1, XY: 1, AW: 1}
| Premise DY ∥ DW gives a linear equation with coefficients {DW: 1, DY: -1}
| Then {UZ: -1, BC: -1, DZ: 1, OW: -1, XY: 1, AW: 1} + 1 x {DW: 1, DY: -1}
|    = {UZ: -1, BC: -1, DZ: 1, DW: 1, OW: -1, XY: 1, AW: 1, DY: -1}
| Premise DY ∥ XY gives a linear equation with coefficients {DY: 1, XY: -1}
| Then {UZ: -1, BC: -1, DZ: 1, DW: 1, OW: -1, XY: 1, AW: 1, DY: -1} + 1 x {DY: 1, XY: -1}
|    = {UZ: -1, BC: -1, DZ: 1, DW: 1, OW: -1, AW: 1}
| Premise OW ∥ AW gives a linear equation with coefficients {AW: 1, OW: -1}
| Then {UZ: -1, BC: -1, DZ: 1, DW: 1, OW: -1, AW: 1} + -1 x {AW: 1, OW: -1}
|    = {UZ: -1, BC: -1, DZ: 1, DW: 1}
| Premise BC ⟂ DW gives a linear equation with coefficients {BC: 1, DW: -1}
| Then {UZ: -1, BC: -1, DZ: 1, DW: 1} + 1 x {BC: 1, DW: -1}
|    = {UZ: -1, DZ: 1}
We are left with a linear equation with coefficients {UZ: -1, DZ: 1} that gives DZ ⟂ UZ

End of proof.
